ALTER TABLE public.supplier_item_notice_attempt DROP CONSTRAINT IF EXISTS supplier_item_notice_manual_sent_shape;--> statement-breakpoint
ALTER TABLE "supplier_item_notice_attempt" ADD CONSTRAINT "supplier_item_notice_manual_sent_shape" CHECK (("supplier_item_notice_attempt"."state" in ('MANUAL_SENT','SUPPLIER_STOP_CONFIRMED','SUPPLIER_CONTINUING','UNABLE_TO_CONFIRM') and (("supplier_item_notice_attempt"."manual_reference" is null and "supplier_item_notice_attempt"."sent_at" is null) or ("supplier_item_notice_attempt"."manual_reference" is not null and "supplier_item_notice_attempt"."sent_at" is not null))) or ("supplier_item_notice_attempt"."state" not in ('MANUAL_SENT','SUPPLIER_STOP_CONFIRMED','SUPPLIER_CONTINUING','UNABLE_TO_CONFIRM') and "supplier_item_notice_attempt"."manual_reference" is null and "supplier_item_notice_attempt"."sent_at" is null));
